): asserts def is Record<string, unknown> {
	if (!def || typeof def !== "object" || Array.isArray(def)) {
		throw new ArkEnvError([
			{
				path: "",
				message:
					'Invalid schema: expected an object mapping in "standard" mode.',
			},
		]);
	}
}
